package com.flamingo.comm.llp.spec;

import com.flamingo.comm.llp.LLPError;
import tools.jackson.databind.JsonNode;

import java.util.ArrayList;
import java.util.HexFormat;
import java.util.List;
import java.util.Locale;

/**
 * One case of the LLP 4.0.0 conformance corpus, typed.
 *
 * <p>The corpus is generated by {@code llp-spec/tools/build_vectors.py} and
 * described by {@code schema/vector.schema.json} (2.0.0). Fields that do not
 * apply to a kind keep a neutral default, so a test can read them without
 * null checks beyond the ones the kind implies.</p>
 *
 * @param file             source JSON file, for failure messages
 * @param id               case id
 * @param kind             encode, decode or stream
 * @param result           Wycheproof-style expectation
 * @param flags            extra annotations
 * @param note             optional prose
 * @param channel          channel of an encode case
 * @param payload          payload of an encode case
 * @param frame            frame of an encode case, or the compact frame of a decode case
 * @param capacity         parser capacity of a decode or stream case
 * @param timeoutMs        inter-byte timeout of a decode or stream case
 * @param steps            decode steps, always expanded to {@code (byte, dtMs)}
 * @param chunks           stream chunks, empty for non-stream cases
 * @param expectedFrames   frames that must be delivered, in order
 * @param expectedErrors   errors that must be reported, in order
 * @param expectedTimeouts value of the timeout counter after the run
 */
public record TestCase(
        String file,
        String id,
        Kind kind,
        Result result,
        List<String> flags,
        String note,
        int channel,
        byte[] payload,
        byte[] frame,
        int capacity,
        int timeoutMs,
        List<Step> steps,
        List<byte[]> chunks,
        List<ExpectedFrame> expectedFrames,
        List<LLPError> expectedErrors,
        int expectedTimeouts) {

    /** Case kinds of the v4 schema. */
    public enum Kind {
        /** {@code (channel, payload)} must produce exactly {@code frame}. */
        ENCODE,
        /** A byte stream fed one byte at a time. */
        DECODE,
        /** A byte stream fed in chunks. */
        STREAM
    }

    /** Wycheproof-style result model. */
    public enum Result {
        /** Must be accepted and produce no error event. */
        VALID,
        /** Must report at least one error event. */
        INVALID,
        /** Implementation-defined; any conformant behaviour is allowed. */
        ACCEPTABLE
    }

    /** One {@code (byte, dt_ms)} step of a decode case. */
    public record Step(byte value, int dtMs) {
    }

    /** A frame that must be delivered. */
    public record ExpectedFrame(int channel, byte[] payload) {
    }

    private static final HexFormat HEX = HexFormat.of();

    /**
     * Parses one case from its JSON node.
     *
     * @param file source file name
     * @param node the case object
     * @return the typed case
     */
    public static TestCase from(String file, JsonNode node) {
        Kind kind = Kind.valueOf(node.get("kind").asString().toUpperCase(Locale.ROOT));
        Result result = Result.valueOf(node.get("result").asString().toUpperCase(Locale.ROOT));

        List<String> flags = new ArrayList<>();
        JsonNode flagsNode = node.get("flags");
        if (flagsNode != null) {
            for (JsonNode flag : flagsNode) {
                flags.add(flag.asString());
            }
        }

        String note = node.has("note") ? node.get("note").asString() : "";

        int channel = -1;
        byte[] payload = null;
        byte[] frame = null;
        int capacity = -1;
        int timeoutMs = -1;
        List<Step> steps = new ArrayList<>();
        List<byte[]> chunks = new ArrayList<>();
        List<ExpectedFrame> frames = new ArrayList<>();
        List<LLPError> errors = new ArrayList<>();
        int timeouts = 0;

        switch (kind) {
            case ENCODE -> {
                channel = node.get("channel").asInt();
                payload = parseHex(node.get("payload").asString());
                frame = parseHex(node.get("frame").asString());
            }
            case DECODE -> {
                capacity = node.get("capacity").asInt();
                timeoutMs = node.get("timeout_ms").asInt();
                if (node.has("feed")) {
                    for (JsonNode step : node.get("feed")) {
                        steps.add(new Step(parseHex(step.get("hex").asString())[0], step.get("dt_ms").asInt()));
                    }
                } else {
                    frame = parseHex(node.get("frame").asString());
                    for (byte b : frame) {
                        steps.add(new Step(b, 0));
                    }
                }
            }
            case STREAM -> {
                capacity = node.get("capacity").asInt();
                timeoutMs = node.get("timeout_ms").asInt();
                for (JsonNode chunk : node.get("chunks")) {
                    byte[] bytes = parseHex(chunk.asString());
                    chunks.add(bytes);
                    for (byte b : bytes) {
                        steps.add(new Step(b, 0));
                    }
                }
            }
            default -> throw new IllegalStateException("unhandled kind " + kind);
        }

        JsonNode expect = node.get("expect");
        if (expect != null) {
            for (JsonNode f : expect.get("frames")) {
                frames.add(new ExpectedFrame(f.get("channel").asInt(), parseHex(f.get("payload").asString())));
            }
            for (JsonNode e : expect.get("errors")) {
                errors.add(LLPError.fromWireName(e.asString()));
            }
            timeouts = expect.get("timeouts").asInt();
        }

        return new TestCase(file, node.get("id").asString(), kind, result, List.copyOf(flags), note,
                channel, payload, frame, capacity, timeoutMs, List.copyOf(steps), List.copyOf(chunks),
                List.copyOf(frames), List.copyOf(errors), timeouts);
    }

    /**
     * Parses a lowercase hex string; the empty string yields an empty array.
     *
     * @param hex hexadecimal text
     * @return the bytes
     */
    public static byte[] parseHex(String hex) {
        return hex.isEmpty() ? new byte[0] : HEX.parseHex(hex);
    }

    @Override
    public String toString() {
        return file + ":" + id;
    }
}
